// Runs the real Mermaid parser over the Python `ef.to_mermaid` goldens (issue #169) so a
// syntax regression in emergentflow/codegen/mermaid.py fails CI. The goldens are generated by
// `uv run pytest tests/test_mermaid_golden.py --snapshot-update`; they cross the ui/ boundary as
// data (raw text), never as a code import.
import mermaid from "mermaid";
import { describe, expect, it } from "vitest";

const GOLDENS = import.meta.glob("../../../tests/golden/mermaid/*.mmd", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

// Undo Mermaid's entity placeholders (its own `decodeEntities`) and HTML entities, then drop
// the `<br/><small>type</small>` suffix, yielding the text a reader actually sees.
function decodeMermaidText(text: string): string {
  const html = text
    .replace(/ﬂ°°/g, "&#")
    .replace(/ﬂ°/g, "&")
    .replace(/¶ß/g, ";")
    .replace(/<br\s*\/?>\s*<small>.*<\/small>$/, "");
  const el = document.createElement("textarea");
  el.innerHTML = html;
  return el.value;
}

describe("ef.to_mermaid goldens", () => {
  it("finds the golden files", () => {
    expect(Object.keys(GOLDENS).length).toBeGreaterThanOrEqual(4);
  });

  it.each(Object.entries(GOLDENS))(
    "%s parses with the real Mermaid parser",
    async (_path, source) => {
      await expect(mermaid.parse(source)).resolves.toBeTruthy();
    },
  );

  it("keeps every vertex and edge of hostile_labels (a 'direction TB' label is not swallowed)", async () => {
    // Mermaid's lexer swallows any line matching `direction\s+(TB|…)` as a direction statement:
    // parse() still succeeds but the node/edge silently vanishes, so check what was parsed.
    const source = Object.entries(GOLDENS).find(([p]) =>
      p.endsWith("/hostile_labels.mmd"),
    )?.[1];
    expect(source).toContain("direction#32;TB");
    const diagram = await mermaid.mermaidAPI.getDiagramFromText(source!);
    const db = diagram.db as unknown as {
      getVertices(): Map<string, { text?: string }>;
      getEdges(): unknown[];
      getDirection(): string;
    };
    const vertices = db.getVertices();
    expect([...vertices.keys()].sort()).toEqual([
      "n_fit",
      "n_impute",
      "n_lifestyle",
      "n_load",
      "n_note",
    ]);
    // A swallowed declaration still leaves an id-only vertex behind via its edges/classes.
    expect(vertices.get("n_fit")?.text).toContain("Fit model");
    // getDiagramFromText runs Mermaid's pre-parse `encodeEntities`, which drops the last `;` of
    // any line matching `style.*:\S*#.*;` -- a literal `:` would corrupt `#lt;30` here.
    expect(decodeMermaidText(vertices.get("n_lifestyle")?.text ?? "")).toBe(
      "Lifestyle:<30 & style:50%",
    );
    expect(db.getEdges()).toHaveLength(3);
    expect(db.getDirection()).toBe("LR");
  });

  it("rejects an unescaped quote (sanity check that parse is strict)", async () => {
    await expect(
      mermaid.parse('flowchart LR\n  a["x"y"]'),
    ).rejects.toBeTruthy();
  });
});
